import SelectPool from '@/components/selectPool'
import { CoinPairImage } from '@cetus/ui-kit'
import { d, textEllipses } from '@cetus/utils'
import { Box, HStack, Text } from '@chakra-ui/react'
import CompletedBlock from '../CompletedBlock'
import { SelectCLMMTokenProps } from './type'

function SelectCLMMToken({
  onEdit,
  editStep,
  currentStep,
  onContinue,
  baseToken,
  quoteToken,
  onBaseTokenChange,
  onQuoteTokenChange,
  quoteWhiteTokenList,
  feeTier,
  feeTierList,
  onFeeTierChange
}: SelectCLMMTokenProps) {
  return (
    <>
      {editStep === 1 || currentStep === 1 ? (
        <SelectPool
          poolType="clmm"
          title="Select pair"
          description="Select the token you want to create a liquidity pool for."
          onContinue={onContinue}
          baseToken={baseToken}
          onBaseTokenChange={onBaseTokenChange}
          quoteToken={quoteToken}
          onQuoteTokenChange={onQuoteTokenChange}
          quoteWhiteTokenList={quoteWhiteTokenList}
          feeTier={feeTier}
          feeTierList={feeTierList}
          onFeeTierChange={onFeeTierChange}
          wrapStyle={{ p: { base: '16px 8px', lg: '32px' } }}
          fromSource="createPool"
        />
      ) : (
        <CompletedBlock onEdit={onEdit}>
          <HStack gap="12px">
            <CoinPairImage
              coinAIconUrl={baseToken?.logo_url}
              coinBIconUrl={quoteToken?.logo_url}
              coinACoinType={baseToken?.coin_type}
              coinBCoinType={quoteToken?.coin_type}
              w="36px"
              h="36px"
            />
            <HStack>
              <Text color="text_caption" fontWeight="500">{`${textEllipses(baseToken?.symbol)} - ${textEllipses(quoteToken?.symbol)}`}</Text>
              <Box h="16px" p="1px 8px" borderRadius="16px" border="1px solid" borderColor="border" bg="bg_secondary">
                <Text fontSize="12px" fontWeight="500" color="text_highlight">
                  {typeof feeTier === 'string' ? `${d(feeTier).div(100).toString()}%` : feeTier?.feeDisplay}
                </Text>
              </Box>
            </HStack>
          </HStack>
        </CompletedBlock>
      )}
    </>
  )
}

export default SelectCLMMToken
